corrected_code:
const express = require('express');
const { nxAuth } = require('../middleware/nxAuth');
const { TaskArtifact } = require('../models/nxArtifact');

const app = express();

app.get('/nx-cloud/artifacts/:taskId', nxAuth, async (req, res) => {
  const { taskId } = req.params;

  // Ensure task artifact belongs to the caller's authorized Nx workspace
  const taskArtifact = await TaskArtifact.findOne({
    where: {
      taskId,
      workspaceId: req.nxContext.workspaceId
    }
  });

  if (!taskArtifact) {
    return res.status(404).json({ error: 'Nx task artifact not found or access denied' });
  }

  res.setHeader('Content-Type', 'application/gzip');
  res.setHeader('x-nx-task-status', taskArtifact.status);
  res.sendFile(taskArtifact.filePath);
});

module.exports = app;
